#!/usr/bin/env python3
"""Convert recipes.json (extracted from the server's jars) to recipes.lua for
the Lua harness. recipes.json is the source of truth; regenerate after
re-extracting:  python3 test/fixtures/to_lua.py"""
import json, os
here = os.path.dirname(os.path.abspath(__file__))
data = json.load(open(os.path.join(here, "recipes.json")))
def lua(v, ind=""):
    if isinstance(v, dict):
        items = [f'{ind} [{json.dumps(k)}] = {lua(x, ind + " ")}' for k, x in sorted(v.items())]
        return "{\n" + ",\n".join(items) + "\n" + ind + "}"
    if isinstance(v, list):
        return "{ " + ", ".join(lua(x, ind) for x in v) + " }"
    if isinstance(v, bool): return "true" if v else "false"
    if isinstance(v, (int, float)): return str(v)
    return json.dumps(v)
with open(os.path.join(here, "recipes.lua"), "w") as f:
    f.write("-- GENERATED by to_lua.py from recipes.json (real recipes from the server's jars). Do not edit.\n")
    f.write("return " + lua(data) + "\n")
print("wrote recipes.lua")
